description: >-
  Use once, before the first audit or watch: writes the small Script It runner
  (sit.py, plain Python, no model calls) onto my computer and checks it works.
---
# Install the Script It runner

Everything is one file, plain Python 3.9+ standard library, no pip, no network at install. It runs on MY computer (not the user's). Skip this if `/workspace/script-it/sit.py` already exists.

```
mkdir -p /workspace/script-it && cat > /workspace/script-it/sit.py <<'EOF'
#!/usr/bin/env python3
"""Script It: plain-script watches. No model calls. Python 3.9+ stdlib only.
usage: sit.py audit '<json tasks>' [--change 0.1] [--inbox N] | add '<json watch>' | list | status | remove ID | pause ID | resume ID
       sit.py check ID [--expect TEXT] | run [--quiet] [--only ID] [--all] [--no-wake] | changes [--ack] | report
       sit.py schedule [MINUTES] | loop [SECONDS] | selftest"""
import hashlib, json, os, re, subprocess, sys, time, urllib.request, urllib.parse
try: import fcntl
except ImportError: fcntl = None
HOME = os.path.expanduser(os.environ.get("SCRIPT_IT_HOME", "~/.script-it"))
P = lambda *a: os.path.join(HOME, *a)
KINDS = ("fetch", "poll", "diff", "status", "count", "threshold", "archive", "convert", "report", "format", "judgment")
MAXB, MAXOUT = 2 * 1024 * 1024, 8000

def die(msg, fix):
    print("ERROR: %s. Fix: %s." % (msg, fix)); sys.exit(2)
def bad(msg): raise ValueError(msg)
def rj(path, d):
    try:
        with open(path) as f: return json.load(f)
    except (OSError, ValueError): return d
def wj(path, o):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path + ".tmp", "w") as f: json.dump(o, f)
    os.replace(path + ".tmp", path)
def log(msg):
    try:
        os.makedirs(HOME, exist_ok=True)
        if os.path.exists(P("run.log")) and os.path.getsize(P("run.log")) > 200000: os.replace(P("run.log"), P("run.log.1"))
        with open(P("run.log"), "a") as f: f.write(time.strftime("%Y-%m-%dT%H:%M:%S ") + msg[:300] + "\n")
    except OSError: pass
def LW():
    if not os.path.exists(P("watches.json")): return []
    try:
        with open(P("watches.json")) as f: ws = json.load(f)
        if isinstance(ws, list): return ws
    except ValueError: pass
    raise ValueError("watches.json is damaged; nothing was changed. Fix: restore %s (the last good copy) or fix the file" % P("watches.json.bak"))
def SW(ws):
    if os.path.exists(P("watches.json")): open(P("watches.json.bak"), "w").write(open(P("watches.json")).read())
    wj(P("watches.json"), ws)
def secrets():
    env = dict(os.environ)
    try:
        for ln in open(P("secrets.env")):
            if "=" in ln and not ln.lstrip().startswith("#"):
                k, v = ln.strip().split("=", 1); env.setdefault(k.strip(), v.strip().strip("'\""))
    except OSError: pass
    return env
def secret_names(w):
    s, wk = w.get("source", {}), w.get("wake") or {}
    return [n for n in [s.get("auth_env"), wk.get("webhook_url_env")] + list(s.get("env_names") or []) if n]
def scrub(text, env, names):
    for n in names:
        v = env.get(n)
        if v and len(v) >= 6: text = text.replace(v, "[hidden]")
    return text

def audit(tasks, f=0.1, inbox=None):
    rows, keep = [], []
    for t in tasks:
        k = t.get("kind")
        if k not in KINDS: die("kind of '%s' must be one of %s" % (t.get("name"), "/".join(KINDS)), "pick the closest kind")
        r = float(t.get("runs_per_day", 0)); nj = t.get("needs_judgment") or k == "judgment"
        if nj and not t.get("prefilter"):
            keep.append({"name": t["name"], "runs_per_day": r, "class": "needs the bot", "why": "judgment, writing or a decision; keep as a bot turn"}); continue
        part = bool(nj)
        form = "builtin watch" if k in ("fetch", "poll", "diff", "status", "count", "threshold") else "script watch (own script in scripts/)"
        after = r * f if part else 0.0
        rows.append({"name": t["name"], "kind": k, "class": "partly scriptable (script pre-filter, bot only on change)" if part else "scriptable",
                     "runs_per_day": r, "form": form, "est_bot_turns_per_day_after": round(after, 2), "est_turns_saved_per_day": round(r - after, 2)})
    rows.sort(key=lambda x: -x["est_turns_saved_per_day"])
    cov = sum(x["runs_per_day"] for x in rows); pr = sum(x["runs_per_day"] for x in rows if "partly" in x["class"])
    after = sum(x["est_bot_turns_per_day_after"] for x in rows) if inbox is None else min(inbox, pr)
    print(json.dumps({"note": "ESTIMATE by arithmetic from your numbers and an assumed change rate of %g; not measured. Adding watches and reading changes also cost bot turns." % f,
        "ranked": rows, "keep": keep, "bot_turns_per_day_on_convertible_tasks_today": round(cov, 2),
        "est_after": round(after, 2), "est_saved": round(cov - after, 2)}, indent=1))

def fetch_http(s, env):
    u = urllib.parse.urlparse(s["url"])
    if not (u.scheme == "https" or (u.scheme == "http" and u.hostname in ("localhost", "127.0.0.1"))): bad("only https or localhost addresses are allowed")
    h = {"User-Agent": "script-it/2"}
    if s.get("auth_env"):
        if not env.get(s["auth_env"]): bad("secret %s is not set" % s["auth_env"])
        h["Authorization"] = "Bearer " + env[s["auth_env"]]
    class NoRedir(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *a, **k): return None
    tmo = float(s.get("timeout", 20)); end = time.monotonic() + tmo
    r = urllib.request.build_opener(NoRedir).open(urllib.request.Request(s["url"], headers=h), timeout=tmo)
    buf = b""
    while len(buf) <= MAXB:
        if time.monotonic() > end: raise TimeoutError("download took longer than %gs" % tmo)
        c = r.read(65536)
        if not c: break
        buf += c
    if len(buf) > MAXB: bad("response over 2 MB")
    cl = r.headers.get("Content-Length")
    if cl and cl.isdigit() and int(cl) != len(buf): bad("partial response (got %d of %s bytes)" % (len(buf), cl))
    return buf.decode("utf-8", "replace")

def fetch_script(s, env):
    p = os.path.realpath(os.path.expanduser(s["path"]))
    if os.path.dirname(p) != os.path.realpath(P("scripts")): bad("scripts must live in %s" % P("scripts"))
    if not os.path.isfile(p): bad("script file not found")
    names = list(s.get("env_names") or [])
    e = {"PATH": os.environ.get("PATH", "/usr/bin:/bin"), "SCRIPT_IT_HOME": HOME}
    e.update({n: env[n] for n in names if env.get(n)})
    try: r = subprocess.run([sys.executable, p], cwd=HOME, env=e, capture_output=True, timeout=float(s.get("timeout", 60)))
    except subprocess.TimeoutExpired: raise TimeoutError("script ran longer than %gs and was stopped" % float(s.get("timeout", 60)))
    out, err = r.stdout[:MAXB].decode("utf-8", "replace"), r.stderr[-300:].decode("utf-8", "replace")
    if r.returncode != 0: bad("script exited %d: %s" % (r.returncode, scrub(err.strip(), env, names)))
    for n in names:
        if env.get(n) and len(env[n]) >= 6 and env[n] in out: bad("script output contained a secret value; not saved")
    return out

def get_value(w, env):
    s = w["source"]
    if s["type"] == "file":
        if not os.path.isfile(s["path"]): bad("file not found: %s" % s["path"])
        if os.path.getsize(s["path"]) > MAXB: bad("file over 2 MB")
        text = open(s["path"], errors="replace").read()
    elif s["type"] == "script": text = fetch_script(s, env)
    else: text = fetch_http(s, env)
    e = w["extract"]; t = e["type"]
    if t == "whole": return text.strip()[:MAXOUT]
    if t == "lines": return [l.strip() for l in text.splitlines() if l.strip()][:500]
    if t == "hash":
        if e.get("ignore_regex"): text = re.sub(e["ignore_regex"], "", text[:256 * 1024])
        return hashlib.sha256(text.encode()).hexdigest()[:16]
    if t == "regex":
        m = re.search(e["pattern"], text[:256 * 1024])
        if not m: bad("regex matched nothing")
        return m.group(1 if m.groups() else 0)
    if t == "json_path":
        try: cur = [json.loads(text)]
        except ValueError: bad("response is not valid JSON (maybe cut off or an error page): %s" % text[:60].replace("\n", " "))
        for part in e["path"].split("."):
            key, star = (part[:-3], True) if part.endswith("[*]") else (part, False)
            nxt = []
            for c in cur:
                if key: c = c.get(key) if isinstance(c, dict) else None
                if c is None: continue
                nxt.extend(c if star and isinstance(c, list) else [c])
            cur = nxt
        if not cur: bad("json path '%s' found nothing" % e["path"])
        return cur if "[*]" in e["path"] else cur[0]
    bad("unknown extract type %s" % t)

def evaluate(w, val, st):
    rule = w["rule"]; r = rule["type"] if isinstance(rule, dict) else rule
    old = st.get("value")
    if r == "any_change":
        st["value"] = val
        return None if old is None or old == val else ("changed", str(old), str(val))
    if r == "threshold":
        try: above = float(val) >= float(rule["value"])
        except (TypeError, ValueError): bad("value '%s' is not a number" % str(val)[:40])
        prev = st.get("above"); st["above"], st["value"] = above, val
        return None if prev is None or prev == above else ("crossed", str(old), str(val))
    if r == "new_items":
        items = [str(x) for x in (val if isinstance(val, list) else [val])]
        seen = st.get("seen"); st["seen"] = sorted(set(items) | set(seen or []))[-500:]
        new = [x for x in items if seen is not None and x not in seen]
        return ("new_items", "", ", ".join(new)) if new else None
    bad("unknown rule %s" % r)

def run(args):
    os.makedirs(HOME, exist_ok=True)
    lock = open(P(".lock"), "w")
    if fcntl:
        try: fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError: log("skipped: another pass is running"); return
    try: ws = LW()
    except ValueError as e: log("FAIL " + str(e)); print("script-it: ERROR: %s" % e); return
    env = secrets()
    quiet, only, force, nowake = "--quiet" in args, (args[args.index("--only") + 1] if "--only" in args else None), "--all" in args, "--no-wake" in args
    ran = chg = nbad = woke = 0; lines = []
    for w in ws:
        if only and w["id"] != only: continue
        if w.get("enabled") is False and not only: continue
        st = rj(P("state", w["id"] + ".json"), {})
        if not (force or only) and time.time() - st.get("ran", 0) < w.get("every_minutes", 60) * 60 - 5: continue
        ran += 1; names = secret_names(w); ch = None; st.setdefault("since", time.time()); st["n_runs"] = st.get("n_runs", 0) + 1
        try:
            val = get_value(w, env); first = "ran" not in st
            ch = evaluate(w, val, st)
            if st.get("fails", 0) >= 3: ch = ("recovered", "", "working again after %d failed checks; the original routine can be paused again" % st["fails"]); st["fallback"] = False
            st["fails"] = 0
            if first: lines.append("baseline %s = %s" % (w["id"], str(val)[:80]))
            log("ok %s%s" % (w["id"], " CHANGE " + ch[0] if ch else ""))
        except Exception as e:
            st["fails"] = st.get("fails", 0) + 1; st["n_fail"] = st.get("n_fail", 0) + 1; nbad += 1
            msg = scrub("%s: %s" % (type(e).__name__, e), env, names)[:200]; log("FAIL %s (%d in a row) %s" % (w["id"], st["fails"], msg))
            if st["fails"] == 3: st["fallback"] = True; ch = ("failure", "", "3 failed checks in a row, last: " + msg)
        st["ran"] = time.time()
        if ch:
            chg += 1; st["n_changes"] = st.get("n_changes", 0) + 1
            seq = sum(1 for _ in open(P("changes.jsonl"))) + 1 if os.path.exists(P("changes.jsonl")) else 1
            rec = {"seq": seq, "watch_id": w["id"], "at": time.strftime("%Y-%m-%dT%H:%M:%S"), "kind": ch[0],
                   "summary": scrub("%s: %s" % (w["name"], ch[2])[:200], env, names), "before": scrub(ch[1], env, names)[:200], "after": scrub(ch[2], env, names)[:200], "seen": False}
            with open(P("changes.jsonl"), "a") as f: f.write(json.dumps(rec) + "\n")
            wu = env.get((w.get("wake") or {}).get("webhook_url_env", ""))
            if wu and not nowake:
                try:
                    body = json.dumps({"text": "script-it: " + rec["summary"]}).encode()[:1000]
                    urllib.request.urlopen(urllib.request.Request(wu, body, {"Content-Type": "application/json"}), timeout=15); woke += 1; st["n_wakes"] = st.get("n_wakes", 0) + 1
                except Exception as e: log("wake failed for %s: %s (the change is saved in changes.jsonl)" % (w["id"], type(e).__name__))
        wj(P("state", w["id"] + ".json"), st)
    if ran and (not quiet or chg) or lines and not quiet:
        print("script-it: ran %d, changed %d, failed %d, woke %d" % (ran, chg, nbad, woke) + ("".join("\n  " + l for l in lines)))

def check(wid, expect):
    w = next((x for x in LW() if x["id"] == wid), None)
    if not w: die("no watch %s" % wid, "run list")
    try: val = get_value(w, secrets())
    except Exception as e: die("%s: %s" % (type(e).__name__, e), "fix the source or the extract; nothing was saved"); return
    shown = json.dumps(val) if not isinstance(val, str) else val
    print("dry run, nothing saved. value:", shown[:500])
    if expect is not None: print("MATCH" if str(expect).strip() == (shown if not isinstance(val, list) else ", ".join(map(str, val))).strip() else "DIFFERENT from the old output: do not switch yet")

def report():
    rows, tb, ta = [], 0.0, 0
    for w in LW():
        st = rj(P("state", w["id"] + ".json"), {}); days = max((time.time() - st.get("since", time.time())) / 86400, 0)
        rep = w.get("replaces_per_day"); before = round(rep * days, 1) if rep is not None else None
        wakes = st.get("n_wakes", 0)
        if before is not None: tb += before; ta += wakes
        rows.append({"watch": w["id"], "days_watched": round(days, 2), "script_passes": st.get("n_runs", 0), "changes": st.get("n_changes", 0), "wake_ups_sent": wakes,
                     "failed_passes": st.get("n_fail", 0), "in_fallback": bool(st.get("fallback")), "est_bot_turns_before": before})
    print(json.dumps({"MEASURED (from this folder's counters)": rows, "ESTIMATE": {"note": "before = replaces_per_day x days watched; after = wake-ups sent. Bot turns for setup and for reading changes are NOT counted.",
        "est_bot_turns_before": round(tb, 1), "wake_ups_sent_on_those": ta, "est_saved": round(tb - ta, 1)}}, indent=1))

def selftest():
    import tempfile, threading, http.server, io, contextlib
    global HOME
    HOME = tempfile.mkdtemp(prefix="sit-selftest-"); os.makedirs(P("scripts")); ok = []
    def t(name, cond): ok.append(cond); print(("PASS " if cond else "FAIL ") + name)
    def ch(): return [json.loads(l) for l in open(P("changes.jsonl"))] if os.path.exists(P("changes.jsonl")) else []
    def run(a):
        with contextlib.redirect_stdout(io.StringIO()): globals()["_run"](a)
    def put(**w): SW([dict(w, **{"id": "w", "name": "W", "every_minutes": 1})])
    f = P("data.txt")
    def setf(s): open(f, "w").write(s)
    class H(http.server.BaseHTTPRequestHandler):
        def do_GET(s):
            try:
                if s.path == "/slow": time.sleep(3)
                s.send_response(200); s.send_header("Content-Length", "50" if s.path == "/cut" else "9"); s.end_headers(); s.wfile.write(b'{"a": 1' + (b"}" if s.path != "/cut" else b""))
            except OSError: pass
        def log_message(*a): pass
    srv = http.server.HTTPServer(("127.0.0.1", 0), H); threading.Thread(target=srv.serve_forever, daemon=True).start(); u = "http://127.0.0.1:%d" % srv.server_port
    setf("a\nb\n"); put(source={"type": "file", "path": f}, extract={"type": "lines"}, rule="new_items"); run(["--all"]); t("baseline makes no change", not ch())
    run(["--all"]); t("quiet re-run makes no change", not ch()); setf("a\nb\nc\n"); run(["--all"]); t("new item detected", len(ch()) == 1 and "c" in ch()[0]["summary"])
    setf("5"); put(source={"type": "file", "path": f}, extract={"type": "whole"}, rule={"type": "threshold", "value": 10}); os.remove(P("changes.jsonl")); os.remove(P("state/w.json"))
    run(["--all"]); setf("12"); run(["--all"]); setf("13"); run(["--all"]); t("threshold fires once per crossing", len(ch()) == 1)
    setf("abc"); run(["--all"]); st = rj(P("state/w.json"), {}); t("non-number counted as a failed check, no crash", st["fails"] == 1 and len(ch()) == 1)
    put(source={"type": "file", "path": P("missing")}, extract={"type": "whole"}, rule="any_change"); os.remove(P("state/w.json")); os.remove(P("changes.jsonl"))
    for _ in range(4): run(["--all"])
    t("3 failures in a row: ONE failure change + fallback flag", [c["kind"] for c in ch()] == ["failure"] and rj(P("state/w.json"), {})["fallback"])
    setf("x"); put(source={"type": "file", "path": f}, extract={"type": "whole"}, rule="any_change"); run(["--all"]); t("recovery is reported once", [c["kind"] for c in ch()][-1] == "recovered")
    for path, why in (("/cut", "cut-off response"), ("/slow", "slow server")):
        put(source={"type": "http_json", "url": u + path, "timeout": 1}, extract={"type": "json_path", "path": "a"}, rule="any_change"); os.remove(P("state/w.json")); run(["--all"])
        t(why + " fails safely", rj(P("state/w.json"), {}).get("fails") == 1)
    open(P("scripts/s.py"), "w").write("import os,sys,time\nm=os.environ.get('MODE')\nif m=='slow': time.sleep(5)\nif m=='boom': sys.exit(3)\nprint(os.environ.get('SECRET9','')+'ok')\n")
    for mode, to, why in (("slow", 1, "slow script is stopped"), ("boom", 5, "script that exits non-zero fails safely")):
        os.environ["MODE"] = mode; put(source={"type": "script", "path": P("scripts/s.py"), "timeout": to, "env_names": ["MODE"]}, extract={"type": "whole"}, rule="any_change")
        os.remove(P("state/w.json")); run(["--all"]); t(why, rj(P("state/w.json"), {}).get("fails") == 1)
    os.environ["MODE"] = "x"; os.environ["SECRET9"] = "sekret-value-1"; put(source={"type": "script", "path": P("scripts/s.py"), "env_names": ["MODE", "SECRET9"]}, extract={"type": "whole"}, rule="any_change")
    os.remove(P("state/w.json")); run(["--all"]); t("secret in script output is not saved", "sekret" not in open(P("state/w.json")).read())
    put(source={"type": "script", "path": "/etc/passwd"}, extract={"type": "whole"}, rule="any_change"); os.remove(P("state/w.json")); run(["--all"]); t("script outside scripts/ is refused", rj(P("state/w.json"), {}).get("fails") == 1)
    srv.shutdown(); print("selftest: %d of %d passed" % (sum(ok), len(ok))); sys.exit(0 if all(ok) else 1)

_run = run
def main():
    a = sys.argv[1:]
    if not a: print(__doc__); return
    c = a[0]
    if c == "selftest": return selftest()
    os.makedirs(HOME, exist_ok=True)
    try: dispatch(c, a)
    except ValueError as e: die(str(e).split(" Fix: ")[0].rstrip(". "), str(e).split(" Fix: ")[-1].rstrip("."))
def dispatch(c, a):
    if c == "audit":
        audit(json.loads(a[1]), float(a[a.index("--change") + 1]) if "--change" in a else 0.1, float(a[a.index("--inbox") + 1]) if "--inbox" in a else None)
    elif c == "add":
        w = json.loads(a[1])
        for k in ("id", "name", "source", "extract", "rule"):
            if k not in w: die("watch needs '%s'" % k, "see the add-script-watch skill for the shape")
        if not re.fullmatch(r"[a-z0-9-]{1,40}", w["id"]): die("id must be lowercase letters, digits, dashes", "rename it")
        s = w["source"]
        if s.get("type") not in ("file", "http_json", "http_text", "script"): die("source type must be file, http_json, http_text or script", "pick one")
        if s["type"] in ("file", "script") and not os.path.isabs(os.path.expanduser(s.get("path", ""))): die("path must be absolute", "give the full path")
        if s["type"] == "script" and os.path.dirname(os.path.realpath(os.path.expanduser(s["path"]))) != os.path.realpath(P("scripts")): die("scripts must live in %s" % P("scripts"), "save the script there first")
        if w["extract"].get("type") not in ("json_path", "regex", "whole", "hash", "lines"): die("extract type must be json_path, regex, whole, hash or lines", "pick one")
        if (w["rule"] if isinstance(w["rule"], str) else w["rule"].get("type")) not in ("any_change", "threshold", "new_items"): die("rule must be any_change, threshold or new_items", "pick one")
        if not isinstance(w.get("every_minutes", 60), int) or w.get("every_minutes", 60) < 1: die("every_minutes must be a whole number of 1 or more", "e.g. 15")
        ws = [x for x in LW() if x["id"] != w["id"]] + [w]; SW(ws); print("added", w["id"])
    elif c in ("list", "status"):
        for w in LW():
            st = rj(P("state", w["id"] + ".json"), {})
            print(w["id"], "|", w["name"], "|", w["source"].get("url") or w["source"].get("path"), "|", w.get("every_minutes", 60), "min",
                  "| PAUSED" if w.get("enabled") is False else "", "| FALLBACK: use the original routine" if st.get("fallback") else "", "| fails in a row: %d" % st.get("fails", 0) if st.get("fails") else "")
    elif c in ("pause", "resume"):
        ws = LW()
        for w in ws:
            if w["id"] == a[1]: w["enabled"] = c == "resume"
        SW(ws); print(c + "d", a[1])
    elif c == "remove":
        SW([x for x in LW() if x["id"] != a[1]]); print("removed", a[1], "(its change history stays in changes.jsonl)")
    elif c == "check": check(a[1], a[a.index("--expect") + 1] if "--expect" in a else None)
    elif c == "run": run(a[1:])
    elif c == "loop":
        while True:
            run(["--quiet"]); time.sleep(max(30, int(a[1])) if len(a) > 1 else 60)
    elif c == "report": report()
    elif c == "changes":
        try: recs = [json.loads(l) for l in open(P("changes.jsonl"))]
        except OSError: recs = []
        new = [r for r in recs if not r["seen"]]
        print(json.dumps([{k: r[k] for k in ("seq", "watch_id", "at", "kind", "summary")} for r in new][:30], indent=1) if new else "no unseen changes")
        if "--ack" in a and recs:
            with open(P("changes.jsonl"), "w") as f: f.writelines(json.dumps(dict(r, seen=True)) + "\n" for r in recs)
    elif c == "schedule":
        m = max(1, int(a[1])) if len(a) > 1 else 15; me = os.path.abspath(__file__)
        print("Paste with `crontab -e` (one line):\n*/%d * * * * SCRIPT_IT_HOME=%s python3 %s run --quiet\nNo cron? Run once in the background instead: SCRIPT_IT_HOME=%s nohup python3 %s loop 60 >> %s/loop.log 2>&1 &" % (m, HOME, me, HOME, me, HOME))
